const originalTranscriptRenderer=transcript,originalReviewRenderer=showResult;
transcript=function(p,t){let pi=t.parts.indexOf(p),saved=read('ielts-transcripts',{}),override=saved[t.id+'-'+pi];let content=override?`<div class="transcript-text">${escapeHTML(override)}</div>`:originalTranscriptRenderer(p,t);return `<div class="transcript-actions"><button class="chip" data-transcript-import="${pi}">${override?'编辑':'导入'}本 Part 原文</button>${override?'<span class="muted">已保存到当前浏览器</span>':''}</div>${content}`};
showResult=function(h){originalReviewRenderer(h);document.querySelectorAll('[data-transcript-import]').forEach(b=>b.onclick=()=>{let t=allTests().find(t=>t.id===h.testId),pi=+b.dataset.transcriptImport,saved=read('ielts-transcripts',{}),d=document.createElement('dialog');d.className='transcript-dialog';d.innerHTML=`<h2>导入听力原文 · Part ${pi+1}</h2><p class="muted">选择纯文本文件，或在下方粘贴与本 Part 对应的听力原文。</p><input type="file" id="transcript-file" accept=".txt,.md,text/plain"><textarea id="transcript-paste" aria-label="听力原文内容" placeholder="在这里粘贴听力原文">${escapeHTML(saved[t.id+'-'+pi]||'')}</textarea><div class="dialog-actions"><button class="secondary" id="transcript-cancel">取消</button><button class="primary" id="transcript-save">保存原文</button></div>`;document.body.append(d);d.showModal();d.querySelector('#transcript-file').onchange=async e=>{let f=e.target.files[0];if(!f)return;if(f.size>1024*1024)return toast('请选择 1 MB 以内的文本文件');d.querySelector('#transcript-paste').value=await f.text()};d.querySelector('#transcript-cancel').onclick=()=>d.remove();d.querySelector('#transcript-save').onclick=()=>{let text=d.querySelector('#transcript-paste').value.trim();if(!text)return toast('请先填入原文内容');saved[t.id+'-'+pi]=text;if(store('ielts-transcripts',saved)){d.remove();showResult(h);toast('听力原文已保存')}}})};
